<?php
declare(strict_types=1);session_start();require_once __DIR__ . '/config/product_step11.php';if(empty($_SESSION['product_fav_csrf']))$_SESSION['product_fav_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['product_fav_csrf'];$error=null;$rows=[];$all=[];
try{$pdo=business_db();product_step11_ensure($pdo);$ctx=product_org_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$productId=(int)($_POST['product_id']??0);$action=(string)($_POST['action']??'add');if($productId<=0)throw new RuntimeException('Choose a product.');if($action==='remove'){$pdo->prepare("DELETE FROM product_favorites WHERE organization_id=? AND user_id IS NULL AND product_id=?")->execute([$orgId,$productId]);}else{$chk=$pdo->prepare("SELECT COUNT(*) FROM product_favorites WHERE organization_id=? AND user_id IS NULL AND product_id=?");$chk->execute([$orgId,$productId]);if(!(int)$chk->fetchColumn())$pdo->prepare("INSERT INTO product_favorites(organization_id,user_id,product_id) VALUES(?,NULL,?)")->execute([$orgId,$productId]);}}
$stmt=$pdo->prepare("SELECT p.id,p.sku,p.product_name,c.category_name FROM product_favorites f JOIN products p ON p.id=f.product_id LEFT JOIN product_categories c ON c.id=p.category_id WHERE f.organization_id=? AND f.user_id IS NULL ORDER BY f.id DESC");$stmt->execute([$orgId]);$rows=$stmt->fetchAll();$all=product_step11_catalog_rows($pdo,$orgId);}catch(Throwable $e){$error=$e->getMessage();}?>
