required><option value="">Choose…</option><?php foreach($all as $p):?><option value="<?= (int)$p['id'] ?>"><?= product_h($p['sku'].' - '.$p['product_name']) ?></option><?php endforeach;?></select></label><button>Add Favorite</button></form></article><article class="os-card pp-span-7"><h2>Favorite Products</h2><?php if(!$rows):?><div class="pp-empty">No favorite products yet.</div><?php else:?><div class="os-links"><?php foreach($rows as $r):?><div class="os-link"><a href="product_detail.php?id=<?= (int)$r['id'] ?>"><b><?= product_h($r['sku'].' • '.$r['product_name']) ?></b><span><?= product_h($r['category_name']) ?></span></a><div style="display:flex;gap:6px"><a href="product_order_builder.php?add=<?= (int)$r['id'] ?>">Add →</a><form method="post"><input type="hidden" name="csrf" value="<?= product_h($csrf) ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?= (int)$r['id'] ?>"><button class="os-btn" style="min-height:30px">Remove</button></form></div></div><?php endforeach;?></div><?php endif;?></article></section><?php endif;?></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
